// Row types for D1 results + the Hono environment type.
// `Env` itself is generated by `wrangler types` (worker-configuration.d.ts).

export interface AppEnv {
  Bindings: Env;
  Variables: {
    /** set by requireAuth */
    user: ProfileRow;
  };
}

export interface ProfileRow {
  id: string;
  phone: string;
  first_name: string;
  photo_r2_key: string | null;
  about: string;
  interests: string; // JSON
  languages: string; // JSON
  mobility: "walk" | "ride" | "home";
  birth_year: number | null;
  verified: number;
  volunteer_requested: number;
  is_volunteer: number;
  role: "user" | "admin";
  lat: number | null;
  lng: number | null;
  radius_km: number;
  text_size: "normal" | "large" | "xlarge";
  theme: "light" | "dark" | "contrast";
  language: "el" | "en";
  push_enabled: number;
  status: "active" | "disabled";
  consent_version: string | null;
  consent_at: string | null;
  created_at: string;
}

export interface TrustedContactRow {
  id: string;
  user_id: string;
  name: string;
  phone: string;
  relationship: "child" | "sibling" | "friend" | "carer" | "other";
  notify: number;
  created_at: string;
}

export interface SessionRow {
  token_hash: string;
  user_id: string;
  expires_at: string;
  revoked: number;
  created_at: string;
}

export interface DeviceRow {
  push_token: string;
  user_id: string;
  platform: string;
  created_at: string;
}

export interface RequestRow {
  id: string;
  user_id: string;
  activity: string;
  starts_at: string;
  place_type: string;
  lat: number;
  lng: number;
  radius_km: number;
  status: "open" | "matched" | "done" | "cancelled";
  created_at: string;
}

export interface ResponseRow {
  id: string;
  request_id: string;
  responder_id: string;
  status: "offered" | "accepted" | "declined";
  created_at: string;
}

export interface MatchRow {
  id: string;
  user_a: string;
  user_b: string;
  source: "discover" | "request";
  status: "active" | "ended";
  created_at: string;
}

export interface MessageRow {
  id: string;
  match_id: string;
  sender_id: string;
  body: string;
  flagged: number; // 0 clean · 1 flagged · 2 held
  created_at: string;
}

export interface PlanRow {
  id: string;
  match_id: string;
  place_name: string;
  place_lat: number | null;
  place_lng: number | null;
  starts_at: string;
  status: "planned" | "done" | "cancelled";
  safe_checkin_at: string | null;
  shared_with_contact_at: string | null;
  checkin_missed_notified_at: string | null;
  reminder_sent_at: string | null;
  created_at: string;
}

export interface ReportRow {
  id: string;
  reporter_id: string | null;
  target_id: string | null;
  reason: "scam" | "harassment" | "fake" | "other";
  details: string | null;
  status: "open" | "actioned" | "dismissed";
  created_at: string;
}

/** A row from the nearby-requests query (request + owner summary + distance). */
export interface NearbyRequestRow extends RequestRow {
  owner_id: string;
  owner_first_name: string;
  owner_photo: string | null;
  owner_about: string;
  owner_interests: string;
  owner_languages: string;
  owner_mobility: "walk" | "ride" | "home";
  owner_verified: number;
  owner_is_volunteer: number;
  owner_birth_year: number | null;
  distance_km: number;
}

/** A row from the nearby-profiles query (profile summary + distance). */
export interface NearbyProfileRow {
  id: string;
  first_name: string;
  photo_r2_key: string | null;
  about: string;
  interests: string;
  languages: string;
  mobility: "walk" | "ride" | "home";
  verified: number;
  is_volunteer: number;
  birth_year: number | null;
  distance_km: number;
}
